; --- 0x0004E1-0x00EFFF  InternalRAM_PadFF -- NOT ROM CONTENT; the payload's RAM/BSS window
; 60,191 bytes. The ROM FILE is 0x30000 bytes and contains only [0x400..0x4FF] at file offset
; 0..255 and [0x0F000..0x3EEFF] at file offset 256.. -- arithmetic check: 256 + 0x2FF00 = 0x30000.
; So 0x000500..0x00EFFF is never emitted; the .fill 0xFF in subcpu_data_tables.s exists purely so
; the .org arithmetic lands 0x0F000 at file offset 256. At run time this window is live DRAM
; holding the payload's variables. Occupants identified while documenting this region:
;   0x000A00-0x000DFF  serial-1 TX ring buffer (1 KiB, mask 0x03FF)
;   0x000E00-0x000E15  serial-1 TX ring descriptor (22 B, template at 0x00F434)
;   0x000E16-0x001015  serial-1 RX ring buffer (512 B, mask 0x01FF)
;   0x001016-0x00102B  serial-1 RX ring descriptor (22 B, template at 0x00F44A)
;   0x001034/0x001038  SERIAL_1_VAR_1034 / _1038 (named in subcpu_vectors.s)
;   0x0010E8 DMA_XFER_STATE, 0x0010EA CMD_PROCESSING_STATE, 0x0010EC BYTE_FROM_MAINCPU_LATCH
;   0x0010F0  standard inter-CPU command buffer;  0x001116 E1 buffer;  0x00111C E2 buffer
;   0x00112D-0x001348  18 x 30-byte voice-POOL/section records (see 0x00F507)
;   0x001349-0x001454  27 x 12-byte channel records (see 0x00F52B)
;   0x001040  32-bit free-running tick counter incremented by Timer_AudioTick_Handler
;   0x003B1C  68-byte tone-generator voice-parameter scratch (template at 0x012115)
;   0x003B60  DSP command ring consumed by AUDIO_PROCESS_DSP (0x035AC8)
; (errno lives at 0x040C22, outside this window -- see the FP pool at 0x01F63E)
InternalRAM_PadFF:
	.fill 7, 1, 0xff
	.fill 8, 1, 0xff
	.fill 8, 1, 0xff
	.byte 0xff, 0xff, 0xff, 0xff, 0xff, 0xff
; Currently swallowed by InternalRAM_PadFF; it is the last two bytes the payload image supplies
; below 0x0500 (0x4E1..0x4FD are 0xFF filler, 0x4FE = 0x40, 0x4FF = 0x00).
; Bit-flag byte shared with the boot ROM (kn5000_subcpu_boot.s: .equ PAYLOAD_LOADED_FLAG, 0x4FE
; "Bit 6: payload ready, Bit 7: transfer complete").
; Payload writers: INT0_HANDLER sets bit 6 on inter-CPU command 0xE3 ("E3 = payload ready",
; `setda 6, 1278` at 0x020ED4) and CH0_State4_E1_Done clears bit 7 (`resda 7, 1278`).
; ★ The image ships it PRE-SET to 0x40 (bit 6 already 1) before the main CPU ever sends 0xE3.
; No payload code READS it -- it exists for the boot ROM / for external inspection only.
SubCPU_Payload_Loaded_Flag:
	.byte 0x40, 0x00


	.org 0xF000 - 0x400, 0xFF
; --- 0x00F000-0x00F41F  IRAM_FirmwareConfig -- mixed config block, and it is WRITABLE
; Not one object. The boundaries below are measured, not guessed, and they tile the range.
;   0x00F000  u16 PAYLOAD VERSION. 0x008E = 142. Cross-checked against the other two payload
;             images we hold: v140 -> 8c 00, v141 -> 8d 00, v142 -> 8e 00, all at file offset 256
;             of original_ROMs/kn5000_subprogram_v14*.rom. INFERENCE: no payload-side reader
;             exists -- neither the decimal spelling (`grep -w 61440`) nor the hex one
;             (`grep -iE '0x0*f000\b'`) finds an absolute memory operand for this address in the
;             v142 sources; every hit is an immediate (`and wa, 0xF000`, `or wa, 0xF000`,
;             `ldw (xiz + 45), 0xF000`), a `.org`/`.short` directive, or prose. So this is a
;             stamp for the loader or for external inspection.
;   0x00F002-0x00F009  ToneGen_Voice_Active_Bitmap, 8 bytes (see the next entry). Its IMPLIED
;             extent runs to the next symbol at 0x00F420 and is meaningless: everything below
;             sits inside it.
;   0x00F00A-0x00F01D  20 bytes, UNDESCRIBED: FF FF FF FF FF FF FF FF 00 00 00 FF 00 FF 00 FF
;             00 00 00 00. Listed only so the range tiles; no consumer identified.
;             ★ CORRECTED 2026-09-25: 0x00F012-0x00F01D are six RAM variables that DO have
;             readers (AudioLoop_ReinitCounter .. InterCPU_DmaLast_Count, carved below);
;             only 0x00F00A-0x00F011 and three 0xFF high bytes are unreferenced.
;   0x00F01E-0x00F13F  DEFAULT DSP EFFECT-CONFIGURATION IMAGE, 0x122 = 290 bytes. DSP_Reset
;             (0x0360A7) copies it with `ld xiy,0xF01E / ld xix,0x448E / ldw bc,0x91 / ldirw`
;             (0x91 words = 290 B) into the live effect-config buffer at DRAM 0x448E, then
;             re-reads offset +8 of the SOURCE image as `ldw_d16 xiz, 61478` (= 0x00F026) and
;             feeds that word to DSP_WriteAlgoInitPreset / DSP_ApplyAlgoForVoiceType. 290 is the
;             same 0x122 size guard the config path uses elsewhere.
;   0x00F140-0x00F33F  128 x u32 MIXER GAIN CURVE, consumed on DSP2 (MN19413). Strictly
;             increasing, 0x000088C1 first, ending at exactly 0x7FFFFF00 -- the same length and
;             the same terminator as DSP_MixerGain_Curve (0x0131CF), so this is an AMPLITUDE
;             curve.
;             CONSUMER: DSP_MixerCoeff_Compute (0x03C067) reads it at three sites, all
;             `lda_d16 xbc, 61760` (= 0x00F140), scaled 4*WA and 4*DE, and FP_MulAccum64s the two
;             lookups against DSP_MixerGain_Curve[4*BC] before writing the product to DSP2
;             registers 0xD0 and 0xD3. WA/BC/DE are the three main-CPU mixer parameters at DRAM
;             0x45B2/0x45B4/0x45B6 (CmdHandler2C global sub-commands 0x01/0x02/0x06).
;             Its left edge is exact: 0x00F01E + 0x122 = 0x00F140. Its right edge rests on the
;             terminator and on the pool below, NOT on the scan: read unsigned the increasing
;             run is 129 entries long (0x00F340 = 0xEE9AFF00), and what excludes entry 128 is
;             that it is negative as s32.
;             ⚠ RETRACTED from the previous text: the ramp does NOT start "about 0x00F0A0" --
;             0x00F09D-0x00F0BB is a 31-byte run of zeros -- and it is not a frequency curve.
;   0x00F340-0x00F34D  14 bytes that belong to neither neighbour: 0xEE9AFF00, 0x10000003, then
;             six zero bytes. Undescribed.
;   0x00F34E-0x00F41F  DOUBLE-PRECISION LIBM CONSTANT POOL: the head of the pool whose tail is
;             already named FPConst_MaxNorm / FPConst_Zero / FPConst_Ln2 at 0x00F420+. Decoded
;             from the image and matched one-for-one to the `lda_24` operands in
;             subcpu_fp_math.s (line numbers in brackets):
;               0x00F34E 1/3! exact [917, 971]        0x00F356 1/5!  [963]
;               0x00F35E 1/7!  [955]                  0x00F366 1/9!  [947]
;               0x00F36E 1/11! [939]                  0x00F376 1/13! [931]
;                 -- six odd-factorial reciprocals (1/5! onward minimax-trimmed in the last
;                    bits), read in DESCENDING address order = a Horner sin() series; the
;                    routine that reads them says so itself ("begin argument reduction,
;                    a * (1/pi) then modf").
;               0x00F38E 8.908910206761541e-06 [887]  0x00F39E 3.1416015625 [875]
;                 -- a Cody-Waite two-part pi: 3.1416015625 - 8.908910206761541e-06 == pi to the
;                    last bit.
;               0x00F396 1/pi = 0x3FD45F306DC9C883 [795]   0x00F3A6 2.3283e-10 [907]
;               0x00F3AE FLT_EPSILON  0x00F3B2 FLT_MAX  0x00F3B6 FLT_MIN  (single precision)
;               0x00F3BA pi   0x00F3C2 2*pi   0x00F3CA pi/2 (0x3FF921FB54442D18, read by
;                    FP_cos in kn5000_subprogram_v142.s)
;               0x00F3D2 ln 2 = 0x3FE62E42FEFA39EF [2851]   0x00F3DA log10 2   0x00F3E2 ln 10
;               0x00F3EA DBL_EPSILON  0x00F3F2 DBL_MAX  0x00F3FA DBL_MIN  0x00F402 -0.0
;                    (EPSILON/MAX/MIN appear in the same order in both precisions)
;             0x00F40A-0x00F41F did not decode as clean doubles at that alignment and is left
;             undescribed.
;             ★ 0x00F3D2 is where the REAL ln(2) lives. The symbol NAMED FPConst_Ln2 sits at
;             0x00F42C and holds sqrt(2) -- see that entry below, and [UNCERTAIN] in
;             ../../symbols/proposals/subcpu-region-01.txt.
;   ★ See the next entry: this block is not read-only config.
IRAM_FirmwareConfig:
	.short 142		; payload version 1.42 (0x008E); see the banner
; 8 bytes (0x00F002-0x00F009) = a 64-bit "this voice is sounding" bitmap, one bit per hardware
; voice, byte index = voice>>3. It sits inside the block currently labelled IRAM_FirmwareConfig.
; Reached ONLY indirectly: ToneGen_Voice_Bitmap_Ptr (0x01F41C) holds the 32-bit pointer 0x0000F002
; and every access goes `ldl_da xbc, 0x01f41c` first.
; Writers:  ToneGen_Poll_Set/ClearBit (0x03D27A / 0x03D298) -- OR/AND-NOT of a single bit,
;           driven by what ToneGen_Poll_Read (0x03D230) reads back from 0x110002 then 0x110000
;           with PORT 6 bit 7 (SFR 0x18 = P6) toggled -- [INFERENCE] that the pin is A23;
;           ToneGen_Clear_Voice_Loop (0x03D203) zeroes all 8 bytes (`cp hl,0x8`).
; ★ In the shipped image these 8 bytes are 0xFF FF FF FF FF FF FF FF -- i.e. all 64 voices are
;   marked BUSY until something clears them. See FINDINGS.
ToneGen_Voice_Active_Bitmap:
	.byte 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff
; --- 0x00F00A-0x00F011  8 bytes 0xFF after the voice bitmap.
; No reader found: no absolute operand (hex or decimal, :16 or :24) and no 3-byte LE
; value in the image names an address in this range.  Purpose not established.
IRAM_Unreferenced_F00A:
	.byte 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff
; --- 0x00F012-0x00F01D  six RAM variables (initial values as shipped).  The banner above
; lists 0x00F00A-0x00F01D as "UNDESCRIBED ... no consumer identified"; these twelve bytes
; do have consumers, all through the 16-bit absolute form `(addr:16)`:
; u16, read and written by AudioLoop_CheckPeriodicReinit (0x01FAFF): incremented on every
; periodic re-init, reset to 0 once it passes 0x0A.
AudioLoop_ReinitCounter:	.short 0
; u8, Timer_AudioTick_Handler (0x01FB41) reads it, increments it and dispatches on the old
; value 0..5 through AudioTick_CaseOffsets; AudioTick_Variant_6 (0x01FB97) resets it to 0.
AudioTick_Phase:	.byte 0
	.byte 0xff		; not referenced (high byte of a word slot)
; u8, counted 0..7 by AudioTick_Variant_6 (0x01FB97); at 8 it sets bit 5 of (0x103E) and
; restarts from 0.
AudioTick_Phase6Count:	.byte 0
	.byte 0xff		; not referenced
; u8, `inc 1,(this)` by the DMA-stuck recovery in Cmd_Check_DMA_Timeout (0x020FD9): the
; number of inter-CPU DMA transfers it has aborted.
InterCPU_DmaAbort_Count:	.byte 0
	.byte 0xff		; not referenced
; u16, Cmd_Check_DMA_Timeout (0x020FD9): incremented while the DMA byte count (control
; register 0x40) has not moved since the last check, reset when it moves or DMA is idle;
; above 0x0A the transfer is aborted.
InterCPU_DmaStuck_Count:	.short 0
; u16, Cmd_Check_DMA_Timeout: the DMA byte count seen at the previous check.
InterCPU_DmaLast_Count:	.short 0
; --- 0x00F01E-0x00F13F  DEFAULT DSP EFFECT-CONFIGURATION IMAGE, 290 bytes (see the banner).
; DSP_Reset (0x0360A7) copies it `ld xiy,this / ld xix,0x448E / ldw bc,0x91 / ldirw` (0x91
; words) into the live effect-config buffer at DRAM 0x448E, then reads the word at +8 of
; THIS image `ld iz,(this+8:16)` and passes it to DSP_WriteAlgoInitPreset and
; DSP_ApplyAlgoForVoiceType.
DSP_DefaultEffectConfig_Image:
	.byte 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00
