	.short 0x5000, 0x6000, 0x6000, 0x7000, 0x0000, 0x0000, 0x1000, 0x2000
	.short 0x2000, 0x3000, 0x4000, 0x4000, 0x5000, 0x6000, 0x6000, 0x7000
