; --- 0x010FCE-0x011015  DSP_AlgoChannel_SelectorRecords -- 12 x 6 bytes
; Per-algorithm-type selector records: byte at 0x010FCE + 6*type + 2*channel
; (three 2-byte channel pairs per type). 0xFF = "no entry" sentinel. The
; DSP_AlgoType_Dispatch arms use the byte as a row selector into the 0x66-stride
; curve pool at 0x011016; DSP_ChanFreq_WritePacket1/2 read the type-6/7 fields
; through the fixed bases 0x010FD2 (+4) and 0x010FD3 (+5) below.
