	.byte 0x00, 0x00, 0x00, 0x03, 0xff, 0xff	; type 4
	.byte 0x00, 0x00, 0x00, 0x03, 0xff, 0xff	; type 5
	.byte 0xff, 0xff, 0xff, 0xff, 0x00, 0x03	; type 6
	.byte 0x00, 0x05, 0x00, 0x06, 0x00, 0x05	; type 7
