Str_EffMute_Prefix:
	.asciz "\nEFF "
Str_EffMute_Suffix:
	.asciz " mute."
; DSP_Mute_WithDebug: "\nDSP <n> mute."
; DSP_Mute_WithDebug (0x037EE9) loads each with `lda xwa,(label:24)` and prints it with Debug_Print_String.
Str_DspMute_Prefix:
	.asciz "\nDSP "
Str_DspMute_Suffix:
	.asciz " mute."
; DSP_Unmute_WithDebug: "\nDSP <n> antimute."
