; EFF_WriteHeader (0x0380AB) loads each with `lda xwa,(label:24)` and prints it with Debug_Print_String.
Str_EffHeader_Prefix:
	.asciz "\nEFF "
Str_EffHeader_Suffix:
	.asciz " headder"
