; NOTE: this address ALREADY carries the ELF name ToneGen_WorkArea -- no rename proposed, this
; entry documents it. It is DSP program+parameter data, not a tone-generator work area.
; CORRECTED 2026-08-21: it is passed to DSP_BytecodeInterpreter_Init in XDE by
; DSP_WriteEFFConfig, and to DSP_ParameterWriteEngine in XBC at THREE further sites, all inside
; DSP_WriteParameter (DSP_WriteParam_EFFCase, DSP_WriteParam_EFFCase0xA and
; DSP_WriteParam_Generic). DSP_WriteGlobalConfig does NOT use it -- it uses 0x0147B3. The old
; text named the wrong routines, undercounted the parameter sites, and quoted line numbers
; 44822/44863/44883/44912 that no longer resolve. See UNCERTAIN.
; --- 0x014777-0x0147B2  ToneGen_WorkArea -- the real label, as the NOTE just above says
;     ("DSP_EFFBytecode_ProgramTable" is descriptive text from
;      symbols/proposals/subcpu-region-15.txt, not a symbol)
; 12-byte descriptors for DSP_BytecodeInterpreter_Init: +0,+2,+4,+6 = four words copied into
; the interpreter frame, +8 = long.  Indexed by effect-slot number.  0x0147B3 is the same
; shape and is the table used by DSP_WriteGlobalConfig (program 0 only).
ToneGen_WorkArea:
	.zero 9
	.zero 8
	.zero 8
	.zero 8
	.zero 8
	.zero 8
	.zero 8
	.zero 3
; =============================================================================
; --- 0x0147B3-0x01E17E  DSP effect program + parameter zone (uPD6383 / MN19413)
; =============================================================================
; 39,372 bytes holding the per-effect DSP upload material for all 100 effect-algorithm numbers:
; interpreter BYTECODE streams (the effect microprograms and their coefficient loads) and
; PARAMETER record tables (descriptor + value streams for the runtime parameter-write path).
; Every byte of the zone is carved below; the layout was recovered from the dispatch code in
; kn5000_subprogram_v142.s and cross-checked two independent ways (see CARVE VERIFICATION).
;
; INDEXING. Four parallel 100-entry u32 pointer arrays, indexed by effect number 0..99, drive
; everything.  They live further down this file as typed `.long` arrays -- EFF_AlgoProgram_PtrTable,
; EFF_CoefProgram_PtrTable, DSP_Param_Block_Ptrs_A, DSP_Param_Block_Ptrs_B; until 2026-09-25 they
; were buried inside the DSP_EffA_Param_Values byte run (scripts/converters/carve_v142_dsp_zone_tail.py):
;   0x01ED7C  algorithm bytecode streams   (read by EFF_Change_WithDebug)
;   0x01EF0C  coefficient bytecode streams (read by EFF_Change_WithDebug)
;   0x01F09C  parameter VALUE record tables      (DSP_Param_Block_Ptrs_A,
;             read by DSP_WriteParam_Generic, pushed to DSP_ParameterWriteEngine)
;   0x01F22C  parameter DESCRIPTOR record tables (DSP_Param_Block_Ptrs_B,
;             passed in XDE to DSP_ParameterWriteEngine)
; EFF_Change_WithDebug(slot, effect) uploads algorithm then coefficients via DSP_WriteEFFConfig
; -> DSP_BytecodeInterpreter_Init; slot 1 effects 9/10 bypass the arrays with the hard-coded
; streams at the end of this zone (DSP_Eff09_Slot1_*) and at 0x01E1DE/0x01E342.
; DSP_WriteParameter(1, 9/10, ..) likewise bypasses the arrays with the fixed pairs
; DSP_Eff9_*/DSP_EffA_* that follow this zone.
;
; BYTECODE STREAM GRAMMAR (DSP_BytecodeInterpreter_Loop). A stream is a sequence of
; variable-length instructions [b0, b1, payload...]: opcode = b0 >> 4, total length (header
; included) = ((b0 & 0x0f) << 8) | b1, i.e. a 12-bit big-endian length. Opcodes 0..5 dispatch
; through the word-offset table at 0x014739 into the six upload handlers at
; DSP_Bytecode_Programs (I-RAM/C-RAM group writes); 0xd = SPI bus-idle + task yield; 0xe = send
; payload[0] as a COMMAND and the rest as DATA words; 6..0xc are ignored. The stream ends when
; the PEEKED next byte has high nibble 0xf (the 0xf0 terminator byte is kept with its stream
; below).
;
; RECORD TABLE GRAMMAR (DSP_TableWalk_Search / DSP_TableWalk_SearchWithState). A table is a run
; of records [len_hi, len_lo, id, payload...] where len = (len_hi << 8) | len_lo counts the
; WHOLE record; a record whose first byte is 0xf0 is the end-of-table sentinel.
; DSP_ParameterWriteEngine walks the VALUE table positionally (record n = parameter set n) and
; hands each record body to DSP_PerParameterTranslator, which consumes the id byte and then
; repeats { id, field-index, curve operands... } until the 0x7a terminator: each id is
; dispatched as an opcode (0x21/0x24/0x40 have dedicated arms, 0x61..0x79 go through the offset
; table at 0x014745 to the DSP_Op_0xNN_* arms), and the field-index byte selects a DSP register
; number out of the DESCRIPTOR record with the SAME id (payload byte [field-index], fetched via
; DSP_TableWalk_Search). So: descriptor record = id + register-number list; value record = id +
; curve/interp operand stream ending 0x7a. Every value record below ends in 0x7a and every
; record id is in the dispatch set {21, 24, 40, 61..79}.
;
; CHIP PARTITION. DSP_DispatchCommand/Data take a chip id: 0 = IC311 (NEC uPD6383GF, primary
; effects DSP), 1 = IC310 (MN19413, the second DSP). Effect slots map to chips through the byte
; table at 0x0001ED6D (slots 0-1 -> chip 0, slots 2-4 -> chip 1). NINE effect numbers are IC310
; programs -- 57 STANDARD, 58 PERCUSSIVE, 59 SYMPHONIC, 60 DEEP SPACE, 79 GEQ, 88 ROOM, 89
; KARAOKE, 90 BATH ROOM, 91 STAGE -- their streams carry command 0x30 records (PROVEN:
; dsp/analysis/second-dsp-and-ready.md, finding B1). They are marked [IC310] below; do not feed
; them to a uPD6383-shaped parser.
;
; CARVE VERIFICATION. (a) Grammar walk: starting at DSP_Eff32_Algo_Bytecode (0x0147EF) and
; walking each stream/table to its terminator tiles the zone with ZERO gaps, ending exactly at
; DSP_Eff9_Param_Descriptors (0x01E17F). (b) Pointer arrays: all 400 entries of the four tables
; (non-zero, in-zone) land exactly on walk-derived block starts, never inside a block. Effect
; names read from the main CPU ROM name table (18-byte stride, see dsp/tools/host_side.py
; effect_name); per-program roles from dsp/programs.tsv. The 42 effect numbers whose pointers
; all target the shared NO OPERATION trio are the named stub effects (MODULATION DELAY, SLOW
; ATTACKER, PITCH SHIFTER, STRING, CEL, CELM, PEDAL WAH, DS_D, OVER_D, ...): the firmware ships
; them as a dry pass-through program.
;
; PARAMETER NAMES AND RANGES (d4 enrichment; every claim is MEASURED in the emulator-side
; research repo kn7000_mame). The user-facing parameter NAMES live on the MAIN CPU: an
; 85-entry name table at 0x0324D5 (16 chars + ':', stride 17) with a 2-char unit table at
; 0x03241A; the per-effect ordered name-index list is a UI-object-database property, read
; live from RAM 0x29AC while each edit page was on screen and pixel-verified against the
; LCD (notes/kn5000-dsp-paramlist.md + tools/kn5000_dsp_paramlist_capture.json). Those
; captured lists are quoted per effect below ("UI params"). The value records in this zone
; carry the numeric machinery for exactly those parameters -- per-record semantics of the
; settled translator opcodes (tools/kn5000_dsp_params.py, kn5000-dsp-paramsemantics.md):
;   op61  linear eval -> writer 0x0387E6            op68  ms * 44100/1000 -> DRAM words
;   op62  CURVE_D volume law, 1.00 dB per UI step   op69  value/180 -> degrees (PHASE/PAN)
;   op63  A/B/C curve select -> cell 06 tail level  op6D  desc+8 pair (COMP attack/release)
;   op21  lerp(0x000000..0x666666) = 0..0.8 full    op70  PEQ biquad coeff+state block
;         scale -> cell 90 (universal tail level)   op72  COMP THRESHOLD/RATIO cells
; The UI value range is 0..99 (lerp divisor 0x63); the 100-entry curve tables CURVE_A/B/C/D
; sit in zone A at 0x012483/0x012613/0x0127A3/0x012B33. The two trailing UI controls of
; every effect are VOLUME and REV SEND (paramlist.md section 5); they land on cells 90/06
; (which is which is NOT forced by record order -- honest limit, paramsemantics.md TAIL).
; Descriptor records below carry the cell list as an inline comment per record.
;
; D4 RE-VERIFICATION (independent of the carve): (a) the four pointer arrays were re-read
; and the 42-effect stub set re-derived -- all 42 share the ONE record trio by pointer
; identity, the 12 NAMED members match the list below, and no other stream in the zone is
; byte-identical to the NO OPERATION program; (b) the IC310 partition was re-derived from
; the streams themselves (an effect is IC310's iff a stream instruction carries command
; byte 0x30) and reproduces exactly the nine of second-dsp-and-ready.md B1 -- their labels
; now carry the DSP2_ prefix; (c) every captured UI effect name resolves in the main-ROM
; name table at 0x033568-18*n.
;
; NOTE. The label DSP_Bytecode_Global_Config below is the historical ELF name and is KEPT for
; continuity, but the address is NOT bytecode: it is the 12-byte (all-zero) program-0 DESCRIPTOR
; that DSP_WriteGlobalConfig hands to DSP_BytecodeInterpreter_Init (the actual global-config
; bytecode streams are pushed by its callers and live at 0x01E496.. after this zone). The
; descriptor fields (+0/+2/+4/+6 words, +8 long) are copied into the interpreter frame; program
; 0 is all zeros. The 48 bytes that follow are room for four more unused 12-byte descriptors,
; also zero.
DSP_Bytecode_Global_Config:
	.zero 12
	.zero 48

