; ----- per-slot / per-chip program pointer tables (u32) -----
; EFF_Mute_WithDebug: `sll xwa,2 / ld xbc,EFF_Mute_Program_PtrTable / add xbc,xwa`, slot 0..4.
; Reader EFF_Mute_WithDebug is at 0x037EB4; 5 x u32 program pointers, one per effect slot (its
; entry contract WA = slot 0..4), the program then goes to DSP_WriteEFFConfig.
EFF_Mute_Program_PtrTable:
	.long	EFF_Mute_Program_Slot0		; 0
	.long	EFF_Mute_Program_Slot1		; 1
	.long	EFF_Mute_Program_Slot2		; 2
	.long	EFF_Mute_Program_Slot3		; 3
	.long	EFF_Mute_Program_Slot4		; 4
; DSP_Mute_WithDebug, indexed by chip (four entries, two chips).
; Reader DSP_Mute_WithDebug is at 0x037EE9 (`sll xwa,2 / ld xbc,table`); 4 x u32 program
; pointers -- the count is pinned by DSP_Unmute_Program_PtrTable starting right after.
DSP_Mute_Program_PtrTable:
	.long	DSP_Mute_Program_Chip0		; 0
	.long	DSP_Mute_Program_Chip1		; 1
	.long	DSP_Mute_Program_Chip2		; 2
	.long	DSP_Mute_Program_Chip3		; 3
; DSP_Unmute_WithDebug, indexed by chip.
; Reader DSP_Unmute_WithDebug is at 0x037F1C (`sll xwa,2 / ld xbc,table`); 4 x u32 program
; pointers -- the count is pinned by EFF_Disconnect_Program_PtrTable starting right after.
DSP_Unmute_Program_PtrTable:
	.long	DSP_Unmute_Program_Chip0	; 0
	.long	DSP_Unmute_Program_Chip1	; 1
	.long	DSP_Unmute_Program_Chip2	; 2
	.long	DSP_Unmute_Program_Chip3	; 3
; EFF_Disconnect: entry = table + 12*mode + 4*slot.  Five entries per mode run, but the code's
; mode stride is 12, not 20 -- see the NOTE THE STRIDE in EFF_Disconnect: with mode 1, slots 2-4
; read EFF_Link_Program_PtrTable[0..2].
EFF_Disconnect_Program_PtrTable:
	.long	EFF_Disconnect_Program_Slot0	; 0
	.long	EFF_Disconnect_Program_Slot1	; 1
	.long	EFF_Disconnect_Program_Slot2	; 2
	.long	EFF_Disconnect_Program_Slot3	; 3
	.long	EFF_Disconnect_Program_Slot4	; 4
; EFF_Link: same 12*mode + 4*slot indexing; with mode 1, slots 2-4 would read past this table.
; Reader EFF_Link is at 0x037FAE; 5 x u32 program pointers, one per effect slot 0..4.
EFF_Link_Program_PtrTable:
	.long	EFF_Link_Program_Slot0		; 0
	.long	EFF_Link_Program_Slot1		; 1
	.long	EFF_Link_Program_Slot2		; 2
	.long	EFF_Link_Program_Slot3		; 3
	.long	EFF_Link_Program_Slot4		; 4
; u16 = 0x004D (77). The pivot the velocity curve is scaled about: the touch computation forms
; (VELCURVE_IN[touch] - 77) before applying the per-mode gain. Read with `ldw_da xbc,0x01f418`
; in Keybed_Decode_Event (0x03D11F). Byte-identical to boot-ROM ToneGen_VelCurve_Pivot
; (0xFF802A).
ToneGen_VelCurve_Pivot:
	.byte 0x4d, 0x00
; u16 = 0x0080 (128). The `divs xbc,xde` denominator of the same computation, i.e. the per-mode
; gain byte is a Q7 fixed-point multiplier: the divisor is 128 = 2^7, so gain 0x60 = 96/128 =
; 0.75x. Byte-identical to boot-ROM ToneGen_VelCurve_Divisor (0xFF802C), whose comment says
; Q7; this file said Q8, which would imply a divisor of 256.
ToneGen_VelCurve_Divisor:
	.byte 0x80, 0x00
; u32 = 0x0000F002 -- the only pointer to ToneGen_Voice_Active_Bitmap. Loaded by
; ToneGen_Poll_SetBit / _ClearBit (`ldl_da xbc,0x01f41c`) and, as an add-absolute operand
; (`addda32_24 xwa,128028`), by ToneGen_Clear_Voice_Loop. 128028 = 0x01F41C.
; ★ Because it is a pointer in writable DRAM, corrupting these 4 bytes silently redirects every
;   voice-status update. See FINDINGS.
; ★ LAYOUT: this 4-byte pointer sits BETWEEN ToneGen_VelCurve_Divisor and the TOUCH-MODE
;   PARAMETER TABLE -- the 30 unlabelled bytes that follow it, 0x01F420-0x01F43D, which are
;   10 records of 3 bytes read by Keybed_Decode_Event as byte[0x01F420 + 3*curve] = gain,
;   byte[+1] = output level at the pivot, byte[+2] = trim subtracted for the five black keys,
;   with `curve` = the byte at 0x004A48 (Keybed_Touch_Mode), initialised to 6 by
;   ToneGen_Init (0x03D016) and thereafter written only by Audio_CmdHandler_A0_BF:
;     curve 0: gain   0/128, pivot out 208, black trim  0   <- touch OFF, every note vel 80
;     curve 1: gain  16/128, pivot out 199, black trim  3
;     curve 2: gain  32/128, pivot out 189, black trim  6
;     curve 3: gain  48/128, pivot out 180, black trim  8
;     curve 4: gain  64/128, pivot out 171, black trim 11
;     curve 5: gain  80/128, pivot out 161, black trim 14
;     curve 6: gain  96/128, pivot out 152, black trim 16   <- the default set by ToneGen_Init
;     curve 7: gain 112/128, pivot out 143, black trim 19
;     curve 8: gain 128/128, pivot out 134, black trim 22
;     curve 9: gain 144/128, pivot out 130, black trim 24
;   The row count of 10 is fixed by Audio_CmdHandler_A0_BF's `cp (xbc + 1), 0x9` / `jr ugt`
;   range check, and the run self-describes: the first byte of each record steps
;   0x00,0x10,...,0x90.  The sub-CPU BOOT ROM carries these same six objects byte-for-byte
;   from 0xFF802A but WITHOUT this pointer -- that missing long is the only layout difference
;   between the two copies -- and there the table IS labelled, as ToneGen_VelCurve_ModeParams
;   (0xFF802E).
ToneGen_Voice_Bitmap_Ptr:
	.long ToneGen_Voice_Active_Bitmap	; = 0x0000F002
; --- 0x01F420-0x01F43D  touch-curve parameters, 10 records x 3 bytes {gain (Q7), output
; level at the pivot, black-key trim}, read by Keybed_Decode_Event (0x03D11F) at
; [this + 3*curve], +1 and +2, curve = Keybed_Touch_Mode (0x004A48); 10 rows by
; Audio_CmdHandler_A0_BF's `cp (xbc+1),0x9` check (see the note above).  Same name as the
; byte-identical table in the boot ROM (kn5000_subcpu_boot.s, 0xFF802E).
ToneGen_VelCurve_ModeParams:
	.byte 0, 208, 0		; curve 0
	.byte 16, 199, 3		; curve 1
	.byte 32, 189, 6		; curve 2
	.byte 48, 180, 8		; curve 3
	.byte 64, 171, 11		; curve 4
	.byte 80, 161, 14		; curve 5
	.byte 96, 152, 16		; curve 6
	.byte 112, 143, 19		; curve 7
	.byte 128, 134, 22		; curve 8
	.byte 144, 130, 24		; curve 9
; 256 bytes (0x01F43E-0x01F53D) mapping the RAW KEYBED TOUCH READING 0..255 to the curve
; domain. It is not a MIDI velocity: the index is the high byte of the keybed data word at
; (0x110000), and MIDI velocity is what comes OUT the far end, from 0x01F53E.
; Monotonically DECREASING: 0xFF for inputs 0..8, then 0xFB 0xF6 0xF1 ... down to 0x01 at
; input 0xDE and 0x00 at 0xFE/0xFF. ★ The decreasing sense is a property of the INDEX, not
; of the output: a small raw reading gives a large strength and therefore a LOUD note, so
; [INFERENCE] the reading behaves like a key-travel TIME. The delivered MIDI velocity, out
; of 0x01F53E, RISES with strike strength -- it is a level, not an attenuation.
ToneGen_Velocity_Input_Curve:
	.byte 0xff, 0xff
	.byte 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xfb
	.byte 0xf6, 0xf1, 0xed, 0xea, 0xe6, 0xe3, 0xe0, 0xdd
	.byte 0xdb, 0xd8, 0xd6, 0xd3, 0xd1, 0xcf, 0xcd, 0xcb
	.byte 0xca, 0xc8, 0xc6, 0xc5, 0xc3, 0xc1, 0xc0, 0xbf
	.byte 0xbd, 0xbc, 0xbb, 0xb9, 0xb8, 0xb7, 0xb6, 0xb5
	.byte 0xb3, 0xb2, 0xb1, 0xb0, 0xaf, 0xae, 0xad, 0xac
	.byte 0xab, 0xaa, 0xaa, 0xa9, 0xa8, 0xa7, 0xa6, 0xa5
	.byte 0xa5, 0xa4, 0xa3, 0xa2, 0xa1, 0xa1, 0xa0, 0x9f
	.byte 0x9d, 0x9c, 0x9b, 0x99, 0x98, 0x97, 0x96, 0x95
	.byte 0x93, 0x92, 0x91, 0x90, 0x8f, 0x8e, 0x8d, 0x8c
	.byte 0x8b, 0x8a, 0x8a, 0x89, 0x88, 0x87, 0x86, 0x85
	.byte 0x85, 0x84, 0x83, 0x82, 0x81, 0x81, 0x80, 0x7f
	.ascii "}|{yxwvusrqponmlkjjihgfeedcbaa`_]\\[YXWVUSRQPONMLKJJIHGFEEDCBAA@?=<;987653210/.-,+**)('&%%$#\"!! "
	.byte 0x1f
	.byte 0x1d, 0x1c, 0x1b, 0x19, 0x18, 0x17, 0x16, 0x15
	.byte 0x13, 0x12, 0x11, 0x10, 0x0f, 0x0e, 0x0d, 0x0c
	.byte 0x0b, 0x0a, 0x0a, 0x09, 0x08, 0x07, 0x06, 0x05
	.byte 0x05, 0x04, 0x03, 0x02, 0x01, 0x01, 0x01, 0x01
	.fill 8, 1, 0x01
	.fill 8, 1, 0x01
	.fill 8, 1, 0x01
	.byte 0x01, 0x01, 0x01, 0x01, 0x00, 0x00
; 256 bytes (0x01F53E-0x01F63D), the second half of the touch mapping; the clamped intermediate
; indexes it and the result is stored as the voice's velocity byte at (xwa+1).
; Starts 0x01 then a long run of 0x02 -- a compressive (roughly logarithmic) response.
ToneGen_Velocity_Output_Curve:
	.byte 0x01, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.fill 8, 1, 0x02
	.byte 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x03, 0x03
	.byte 0x03, 0x04, 0x04, 0x04, 0x04, 0x05, 0x05, 0x05
	.byte 0x05, 0x06, 0x06, 0x06, 0x07, 0x07, 0x07, 0x07
	.byte 0x08, 0x08, 0x08, 0x08, 0x09, 0x09, 0x09, 0x0a
	.byte 0x0a, 0x0a, 0x0a, 0x0b, 0x0b, 0x0b, 0x0c, 0x0c
	.byte 0x0c, 0x0c, 0x0d, 0x0d, 0x0d, 0x0d, 0x0e, 0x0e
	.byte 0x0e, 0x0f, 0x0f, 0x0f, 0x0f, 0x10, 0x10, 0x11
	.byte 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19
	.byte 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x21
	.byte 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28, 0x29
	.byte 0x2a, 0x2b, 0x2c, 0x2d, 0x2e, 0x2f, 0x30, 0x31
	.byte 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39
	.byte 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f, 0x40, 0x41
	.byte 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49
	.byte 0x4a, 0x4b, 0x4c, 0x4d, 0x4e, 0x4f, 0x50, 0x51
